import{_ as t,o,c as n,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Tenant API & Webhooks — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API & Webhooks — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/tenant-api-webhooks-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API & Webhooks — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/tenant-api-webhooks-production-readiness"}]]},"headers":[],"relativePath":"deployment/tenant-api-webhooks-production-readiness.md","filePath":"deployment/tenant-api-webhooks-production-readiness.md","lastUpdated":1787963429000}'),r={name:"deployment/tenant-api-webhooks-production-readiness.md"};function s(d,e,i,l,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-webhooks-—-production-readiness" tabindex="-1">Tenant API &amp; Webhooks — Production Readiness <a class="header-anchor" href="#tenant-api-webhooks-—-production-readiness" aria-label="Permalink to &quot;Tenant API &amp; Webhooks — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-21</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — migrate-first</td></tr><tr><td><strong>Scope</strong></td><td>Platform Settings → Developers: integration API tokens + outbound event webhooks</td></tr><tr><td><strong>Companion</strong></td><td><a href="/developer-guide/tenant-api-webhooks">Developer guide</a> · <a href="/api/tenant-v1-developers">API</a> · <a href="/user-guide/tenant-settings#developers">User guide</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Tenant API &amp; Webhooks ships as a <strong>platform</strong> capability (permission <code>settings.manage_developers</code>), not a Marketplace SKU. Operators mint Sanctum integration tokens (<code>es_…</code>) for <code>/api/tenant/v1</code> and subscribe to domain events with signed outbound POSTs.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Migrate-only (<code>token_type</code> short index, webhook tables, permission sync)</td><td><strong>Pass</strong></td></tr><tr><td>No parallel auth / route tree; Sanctum + Spatie unchanged</td><td><strong>Pass</strong></td></tr><tr><td>SSRF guards (private IP / localhost) + <strong>no redirect follow</strong></td><td><strong>Pass</strong></td></tr><tr><td>Timestamped HMAC envelope (<code>{timestamp}.{body}</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Automation still entitled-gated; webhooks independent</td><td><strong>Pass</strong></td></tr><tr><td>Send test does not consume failure budget / auto-disable</td><td><strong>Pass</strong></td></tr><tr><td>Delivery retention (<code>webhooks:prune-deliveries</code> weekly)</td><td><strong>Pass</strong></td></tr><tr><td>Pest Developers + SignedOutboundHttpClient (incl. redirect test)</td><td><strong>Pass</strong></td></tr><tr><td>Playwright Settings → Developers full one-login workflow</td><td><strong>Pass</strong></td></tr><tr><td>Docs + CHANGELOG + roadmap</td><td><strong>Pass</strong></td></tr></tbody></table><hr><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><ol><li>Deploy Backend + Frontend + Docs together.</li><li>Run migrations (includes <code>settings.manage_developers</code> grant to owner/admin defaults). Index name is <code>pat_token_type_tokenable_index</code> (MySQL-safe).</li><li>Ensure a queue worker processes the <code>webhooks</code> queue (include <code>webhooks</code> alongside <code>automations</code> / <code>emails</code> / <code>default</code> on Forge).</li><li>Scheduler already includes <code>webhooks:prune-deliveries --days=90</code> weekly (payload retention).</li><li>Smoke: Settings → Developers → create API token → call a tenant endpoint with Bearer → create webhook → Send test → confirm Recent deliveries.</li></ol><h2 id="operator-notes" tabindex="-1">Operator notes <a class="header-anchor" href="#operator-notes" aria-label="Permalink to &quot;Operator notes&quot;">​</a></h2><ul><li>Integration tokens act as the creating user (<code>abilities: *</code>) — mint via a least-privilege integration user.</li><li>After 10 consecutive <strong>event</strong> delivery failures, endpoints auto-disable; <strong>Send test</strong> does not increment that budget. Operators can Enable again from the UI.</li><li>Outbound HTTP does not follow redirects (SSRF hardening).</li></ul><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Ability/scope matrix beyond “acts as user”</li><li><code>customer_payment.posted</code> event</li><li>Separate OpenAPI / integration-only route tree</li><li>OAuth client credentials</li><li>Full endpoint edit form (name/url/events) — Enable/Disable and rotate/delete are available</li></ul>',13)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
